insert into public.posts(id,type,slug,title,summary,cover_url,category_id,body,status,position,published_at) values
('30000000-0000-0000-0000-000000000001','resource','guia-hardware-software','Guía de hardware y software','Un resumen esencial para repasar los conceptos más importantes.','asset:recursos','10000000-0000-0000-0000-000000000001',E'## Tu guía de repaso\n**Hardware:** componentes físicos. Ejemplos: teclado, CPU, memoria RAM, monitor y disco.\n\n**Software:** programas e instrucciones. Ejemplos: sistema operativo, navegador y procesador de textos.\n\n## Componentes internos\n- CPU: interpreta instrucciones y realiza operaciones.\n- RAM: memoria temporal de los programas abiertos.\n- SSD o disco: conserva datos sin electricidad.\n- Placa base: conecta las piezas.\n- Fuente: proporciona energía.\n\n## El ciclo de la información\nEntrada → procesamiento → salida → almacenamiento.\n\n## Comprueba lo que sabes\n1. Menciona dos ejemplos de hardware.\n2. Explica por qué una aplicación no es hardware.\n3. ¿Dónde se guardan tus documentos al apagar?','published',1,now()),
('30000000-0000-0000-0000-000000000002','resource','glosario-informatico','Glosario informático','Palabras clave para hablar el idioma de la tecnología.','asset:informatica','10000000-0000-0000-0000-000000000001',E'## De la A a la Z\n**Archivo:** conjunto de datos guardado con un nombre.\n\n**Bit:** unidad de información que puede representar 0 o 1.\n\n**Byte:** grupo de ocho bits.\n\n**CPU:** unidad central de procesamiento.\n\n**Dato:** representación de un valor, hecho o símbolo.\n\n**Hardware:** componentes físicos de un sistema informático.\n\n**Informática:** estudio del tratamiento automático de la información.\n\n**Periférico:** dispositivo que intercambia datos con una computadora.\n\n**RAM:** memoria temporal de acceso aleatorio.\n\n**Sistema operativo:** software que administra los recursos del equipo.\n\n**Software:** programas e instrucciones.\n\n**SSD:** unidad de almacenamiento de estado sólido.\n\n**USB:** estándar de conexión para dispositivos.','published',2,now()),
('30000000-0000-0000-0000-000000000003','resource','ficha-perifericos','Ficha de clasificación de periféricos','Organiza los dispositivos según la función que realizan.','asset:perifericos','10000000-0000-0000-0000-000000000002',E'## Clasifica y explica\nCopia los siguientes dispositivos en tu cuaderno y escribe su función: teclado, ratón, micrófono, cámara web, monitor, impresora, altavoces, memoria USB y pantalla táctil.\n\n## Categorías\n- **Entrada:** envía datos hacia el equipo.\n- **Salida:** presenta resultados.\n- **Almacenamiento:** conserva archivos.\n- **Entrada y salida:** cumple ambas funciones.\n\n## Solución orientativa\nEntrada: teclado, ratón, micrófono, cámara. Salida: monitor, impresora, altavoces. Almacenamiento: memoria USB. Entrada y salida: pantalla táctil.\n\n> Explica tu razonamiento. Algunos dispositivos, como una impresora multifunción, pueden pertenecer a más de un grupo.','published',3,now()),
('40000000-0000-0000-0000-000000000001','video','que-es-una-computadora','¿Qué es una computadora?','Una introducción visual a los equipos que usamos cada día.','asset:informatica','10000000-0000-0000-0000-000000000001','Video de Marcelo PC para acompañar la lección de introducción. Fuente: YouTube.','published',1,now()),
('40000000-0000-0000-0000-000000000002','video','hardware-y-software','Hardware y software, en pocas palabras','Descubre la diferencia entre las piezas y los programas.','asset:hw-vs-sw','10000000-0000-0000-0000-000000000001','Video de LearnFree en Español. Observa los ejemplos y relaciónalos con tu computadora.','published',2,now()),
('40000000-0000-0000-0000-000000000003','video','interior-computadora','Un recorrido por la computadora','Reconoce la placa base, el procesador, la RAM y el disco.','asset:componentes','10000000-0000-0000-0000-000000000002','Microaprendizaje de Educar Portal. Los componentes internos aparecen aproximadamente desde el minuto 2:46.','published',3,now()),
('40000000-0000-0000-0000-000000000004','video','perifericos-entrada-salida','Periféricos de entrada y salida','Un repaso sencillo para identificar dispositivos.','asset:perifericos','10000000-0000-0000-0000-000000000002','Video de La Profe Mery. Recurso de repaso básico sobre periféricos.','published',4,now()),
('40000000-0000-0000-0000-000000000005','video','tipos-software','Los tipos de software','Aprende a distinguir sistemas, aplicaciones y herramientas de programación.','asset:tipos-software','10000000-0000-0000-0000-000000000003','Video de Pase de lista. Identifica un ejemplo para cada tipo de software.','published',5,now()),
('50000000-0000-0000-0000-000000000001','software','libreoffice','LibreOffice','Escribe documentos, crea presentaciones y organiza tus ideas.','asset:software','10000000-0000-0000-0000-000000000003',E'## Una suite para crear\nLibreOffice es una suite ofimática libre y de código abierto. Incluye Writer para textos, Calc para hojas de cálculo e Impress para presentaciones.\n\n## En el aula\nPuedes redactar un informe sobre los componentes de la computadora, preparar una presentación o registrar datos en una tabla.','published',1,now()),
('50000000-0000-0000-0000-000000000002','software','tux-paint','Tux Paint','Dibuja, experimenta con formas y crea tus propias ilustraciones.','asset:software','10000000-0000-0000-0000-000000000004',E'## Dibujo digital\nTux Paint es un programa libre y de código abierto pensado para aprender a dibujar de forma sencilla. Sus herramientas permiten experimentar con pinceles, sellos, líneas y figuras.\n\n## Actividad creativa\nCrea un cartel que muestre tres dispositivos de entrada y tres de salida.','published',2,now()),
('50000000-0000-0000-0000-000000000003','software','gcompris','GCompris','Practica el uso del teclado y el ratón con actividades sencillas.','asset:software','10000000-0000-0000-0000-000000000004',E'## Refuerzo de habilidades básicas\nGCompris reúne actividades educativas. Aunque su público principal tiene entre 2 y 10 años, algunas actividades de teclado y ratón pueden servir como refuerzo inicial.\n\nElige las actividades que se ajusten a tus necesidades y avanza a retos más complejos cuando las domines.','published',3,now()),
('60000000-0000-0000-0000-000000000001','simulator','explorador-componentes','Explorador de componentes','Acércate al interior de una computadora y descubre cada pieza.','asset:componentes','10000000-0000-0000-0000-000000000002','Explora CPU, RAM, almacenamiento, placa base, fuente y tarjeta gráfica.','published',1,now()),
('60000000-0000-0000-0000-000000000002','simulator','laboratorio-binario','Laboratorio binario','Enciende bits y descubre cómo se representan los números.','asset:binario','10000000-0000-0000-0000-000000000001','Un byte contiene ocho bits. Cada posición representa una potencia de dos: 128, 64, 32, 16, 8, 4, 2 y 1. Suma los valores de los bits encendidos para obtener el número decimal.','published',2,now()),
('70000000-0000-0000-0000-000000000001','activity','hardware-o-software','¿Hardware o software?','Clasifica ejemplos de la vida cotidiana y comprueba tus respuestas.','asset:hw-vs-sw','10000000-0000-0000-0000-000000000001','Piensa si cada elemento es una pieza física o un conjunto de instrucciones.','published',1,now()),
('70000000-0000-0000-0000-000000000002','activity','clasifica-perifericos','Clasifica los periféricos','Identifica dispositivos de entrada, salida y almacenamiento.','asset:perifericos','10000000-0000-0000-0000-000000000002','Pregunta qué ocurre con los datos: ¿entran, salen o se conservan?','published',2,now()),
('80000000-0000-0000-0000-000000000001','evaluation','fundamentos-informatica','Fundamentos de informática','Pon a prueba tus conocimientos sobre hardware y software.','asset:evaluacion','10000000-0000-0000-0000-000000000001','Una evaluación de repaso de las primeras lecciones. Puedes repetirla cuantas veces quieras. No se guardan resultados individuales.','published',1,now()),
('80000000-0000-0000-0000-000000000002','evaluation','componentes-y-perifericos','Componentes y periféricos','Demuestra lo que sabes del interior y el exterior de la computadora.','asset:componentes','10000000-0000-0000-0000-000000000002','Repasa las funciones de cada componente. Lee todas las opciones antes de responder. No se guardan resultados individuales.','published',2,now());
