insert into public.software(post_id,features,educational_use,install_instructions,usage_instructions,official_url,platforms,practice_activity) values
('50000000-0000-0000-0000-000000000001',array['Procesador de textos','Hojas de cálculo','Presentaciones','Software libre'],'Redactar trabajos y presentar ideas.','Visita la página oficial, elige tu sistema y sigue las instrucciones del instalador. Pide autorización a un adulto.','Abre Writer, crea un documento, escribe un título y guarda el archivo.','https://es.libreoffice.org/descarga/','Windows, macOS y GNU/Linux','Crea una página con una tabla de hardware y software.'),
('50000000-0000-0000-0000-000000000002',array['Pinceles y formas','Sellos','Interfaz sencilla','Software libre'],'Desarrollar creatividad y precisión con el ratón.','Elige el instalador de tu sistema desde la página oficial. Sigue los pasos con ayuda de un adulto.','Selecciona un pincel, dibuja sobre el lienzo y usa Guardar al terminar.','https://tuxpaint.org/download/','Windows, macOS, Android y Linux','Dibuja una computadora y etiqueta sus partes.'),
('50000000-0000-0000-0000-000000000003',array['Actividades de teclado y ratón','Juegos de lógica','Software libre'],'Reforzar destrezas digitales básicas.','Descarga la versión compatible desde la página oficial. En macOS la página ofrece una versión anterior.','Abre la colección y elige una actividad de descubrimiento de la computadora.','https://gcompris.net/downloads-es.html','Windows, Android, GNU/Linux, Raspberry Pi; versión anterior para macOS','Practica una actividad de ratón y describe qué habilidad trabajaste.');
insert into public.simulators(post_id,builtin,objectives,features,instructions,practice_activity,reflection_questions) values
('60000000-0000-0000-0000-000000000001','components',array['Identificar las piezas internas.','Relacionar cada pieza con su función.'],array['Seis componentes','Explicaciones interactivas'],'Selecciona una pieza para consultar su función. Explora las seis antes de completar el reto.','Explica a un compañero por qué la RAM no sustituye al disco.',array['¿Qué pasaría sin una fuente de alimentación?','¿Qué pieza conserva tus archivos?']),
('60000000-0000-0000-0000-000000000002','binary',array['Entender los estados 0 y 1.','Convertir un byte a decimal.'],array['Ocho bits interactivos','Conversión en tiempo real'],'Pulsa cada bit para alternar entre 0 y 1. Observa el valor decimal. También puedes escribir un número de 0 a 255.','Representa los números 5, 10, 42 y 255.',array['¿Cuál es el mayor número con ocho bits?','¿Cuántos valores diferentes puedes representar?']);
