('90000000-0000-0000-0000-000000000001','70000000-0000-0000-0000-000000000001',1,'Un teclado es…','El teclado es una pieza física: hardware.'),
('90000000-0000-0000-0000-000000000002','70000000-0000-0000-0000-000000000001',2,'Un navegador web es…','Un navegador es un programa: software.'),
('90000000-0000-0000-0000-000000000003','70000000-0000-0000-0000-000000000001',3,'La memoria RAM es…','La RAM es un componente físico interno.'),
('90000000-0000-0000-0000-000000000004','70000000-0000-0000-0000-000000000001',4,'El sistema operativo es…','El sistema operativo coordina el hardware mediante instrucciones.'),
('90000000-0000-0000-0000-000000000005','70000000-0000-0000-0000-000000000002',1,'¿Qué función tiene el micrófono?','El micrófono captura sonidos que entran en la computadora.'),
('90000000-0000-0000-0000-000000000006','70000000-0000-0000-0000-000000000002',2,'¿Qué función tiene el monitor?','El monitor presenta imágenes: salida.'),
('90000000-0000-0000-0000-000000000007','70000000-0000-0000-0000-000000000002',3,'¿Qué función principal tiene una memoria USB?','La memoria USB conserva archivos: almacenamiento.'),
('90000000-0000-0000-0000-000000000008','70000000-0000-0000-0000-000000000002',4,'Una pantalla táctil es de…','Muestra imágenes y recibe toques, por eso es de entrada y salida.'),
('90000000-0000-0000-0000-000000000009','80000000-0000-0000-0000-000000000001',1,'¿Qué estudia la informática?','La informática estudia el tratamiento automático de la información.'),
('90000000-0000-0000-0000-000000000010','80000000-0000-0000-0000-000000000001',2,'¿Cuál de estos es hardware?','El ratón es un dispositivo físico.'),
('90000000-0000-0000-0000-000000000011','80000000-0000-0000-0000-000000000001',3,'¿Qué es el software?','El software reúne programas e instrucciones.'),
('90000000-0000-0000-0000-000000000012','80000000-0000-0000-0000-000000000001',4,'¿Cuál es un sistema operativo?','GNU/Linux es un sistema operativo que administra recursos.'),
('90000000-0000-0000-0000-000000000013','80000000-0000-0000-0000-000000000001',5,'¿Qué tipo de software es un procesador de textos?','Es software de aplicación porque resuelve una tarea del usuario.'),
('90000000-0000-0000-0000-000000000014','80000000-0000-0000-0000-000000000001',6,'¿Qué orden describe el ciclo básico?','Primero entran datos, se procesan, se presenta una salida y pueden almacenarse.'),
('90000000-0000-0000-0000-000000000015','80000000-0000-0000-0000-000000000002',1,'¿Qué componente ejecuta instrucciones?','La CPU interpreta y ejecuta las instrucciones.'),
('90000000-0000-0000-0000-000000000016','80000000-0000-0000-0000-000000000002',2,'¿Qué memoria pierde su contenido al apagar?','La RAM es volátil y temporal.'),
('90000000-0000-0000-0000-000000000017','80000000-0000-0000-0000-000000000002',3,'¿Dónde se conservan tus documentos sin electricidad?','El SSD es almacenamiento no volátil.'),
('90000000-0000-0000-0000-000000000018','80000000-0000-0000-0000-000000000002',4,'¿Cuál es un periférico de entrada?','El escáner convierte documentos físicos en datos digitales.'),
('90000000-0000-0000-0000-000000000019','80000000-0000-0000-0000-000000000002',5,'¿Qué conecta los componentes internos?','La placa base conecta las piezas para que se comuniquen.');
