create index podcasts_status_idx on public.podcasts(status);

create policy "Admins upload media" on storage.objects for insert to authenticated with check (bucket_id='aulabyte-media' and public.has_role(auth.uid(),'admin'));
create policy "Admins update media" on storage.objects for update to authenticated using (bucket_id='aulabyte-media' and public.has_role(auth.uid(),'admin'));
create policy "Admins delete media" on storage.objects for delete to authenticated using (bucket_id='aulabyte-media' and public.has_role(auth.uid(),'admin'));
create policy "Published media read" on storage.objects for select to anon,authenticated using (bucket_id='aulabyte-media' and (public.has_role(auth.uid(),'admin') or exists(select 1 from public.posts p where p.status='published' and p.cover_url='storage:'||name) or exists(select 1 from public.resources r join public.posts p on p.id=r.post_id where p.status='published' and r.file_url='storage:'||name) or exists(select 1 from public.videos v join public.posts p on p.id=v.post_id where p.status='published' and v.video_file_url='storage:'||name) or exists(select 1 from public.podcasts p where p.status='published' and (p.cover_url='storage:'||name or p.audio_url='storage:'||name))));






